import React, { useState, useEffect, useContext } from "react";
import { useParams } from "react-router-dom";
import { Container, Card, Spinner, Form, Button, Alert } from "react-bootstrap";
import axios from "axios";
// import { AuthContext } from "../context/AuthContext"; // Import context để kiểm tra đăng nhập

const BlogDetail = () => {
  const { id } = useParams();
  // const { user } = useContext(AuthContext); // Lấy thông tin người dùng từ context
  const [blog, setBlog] = useState(null);
  const [loading, setLoading] = useState(true);
  const [comment, setComment] = useState("");
  const [comments, setComments] = useState([]);

  useEffect(() => {
    axios.get(`http://localhost:9999/api/v1/blogs/${id}`)
      .then((response) => {
        setBlog(response.data);
        setLoading(false);
      })
      .catch((error) => {
        console.error("Error fetching blog details:", error);
        setLoading(false);
      });
  }, [id]);

  const handleCommentSubmit = () => {
    if (!user) return;
    if (comment.trim() === "") return;
    setComments([...comments, comment]);
    setComment("");
  };

  if (loading) return <Spinner animation="border" className="d-block mx-auto mt-5" />;
  if (!blog) return <p className="text-center">Không tìm thấy bài viết</p>;

  return (
    <Container>
      <Card className="mt-4">
        <Card.Img variant="top" src={blog.image?.path || "/default-image.jpg"} alt={blog.title} />
        <Card.Body>
          <Card.Title>{blog.title}</Card.Title>
          <Card.Text>{blog.description}</Card.Text>
          <p><strong>Danh mục:</strong> {blog.category}</p>
          <p><strong>Định dạng:</strong> {blog.image?.mimeType || "Không xác định"}</p>
          <p><small>Đăng bởi: {blog.userId}</small></p>
          <p><small>Ngày tạo: {new Date(blog.createdAt).toLocaleDateString()}</small></p>
        </Card.Body>
      </Card>

      <div className="mt-4">
        <h5>Bình luận</h5>
        {!user ? (
          <Alert variant="warning">Bạn cần đăng nhập để bình luận.</Alert>
        ) : (
          <Form>
            <Form.Group controlId="comment">
              <Form.Control
                type="text"
                placeholder="Viết bình luận..."
                value={comment}
                onChange={(e) => setComment(e.target.value)}
              />
            </Form.Group>
            <Button className="mt-2" onClick={handleCommentSubmit}>Gửi</Button>
          </Form>
        )}
        <ul className="mt-3">
          {comments.map((cmt, index) => (
            <li key={index}>{cmt}</li>
          ))}
        </ul>
      </div>
    </Container>
  );
};

export default BlogDetail;
